const listPaymentGrantsForEntitlement = `-- name: ListPaymentGrantsForEntitlement :many
SELECT id, order_id, settlement_id, remote_payment_id, account_id, offer_id, source, paid_centavos, currency, start_at, end_at, anchor_day, policy_version, capabilities, state, created_at, revoked_at FROM payment_grants
WHERE account_id=$1::uuid AND offer_id=$2
ORDER BY start_at,id
`

type ListPaymentGrantsForEntitlementParams struct {
	AccountID pgtype.UUID `json:"account_id"`
	OfferID   string      `json:"offer_id"`
}

func (q *Queries) ListPaymentGrantsForEntitlement(ctx context.Context, arg ListPaymentGrantsForEntitlementParams) ([]PaymentGrant, error) {
	rows, err := q.db.Query(ctx, listPaymentGrantsForEntitlement, arg.AccountID, arg.OfferID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PaymentGrant
	for rows.Next() {
		var i PaymentGrant
		if err := rows.Scan(
			&i.ID,
			&i.OrderID,
			&i.SettlementID,
			&i.RemotePaymentID,
			&i.AccountID,
			&i.OfferID,
			&i.Source,
			&i.PaidCentavos,
			&i.Currency,
			&i.StartAt,
			&i.EndAt,
			&i.AnchorDay,
			&i.PolicyVersion,
			&i.Capabilities,
			&i.State,
			&i.CreatedAt,
			&i.RevokedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

